package com.scholarshipmatcher.config;
import org.springframework.context.annotation.*; import org.springframework.security.config.annotation.web.builders.HttpSecurity; import org.springframework.security.web.SecurityFilterChain; import org.springframework.security.crypto.bcrypt.BCryptPasswordEncoder; import org.springframework.security.crypto.password.PasswordEncoder; import org.springframework.beans.factory.annotation.Value; import org.springframework.web.cors.*; import org.springframework.security.web.csrf.CookieCsrfTokenRepository; import org.springframework.security.web.csrf.CsrfTokenRequestAttributeHandler; import java.util.List;
@Configuration public class SecurityConfig {
 @Bean PasswordEncoder passwordEncoder(){return new BCryptPasswordEncoder();}
 @Bean SecurityFilterChain filterChain(HttpSecurity http) throws Exception {var handler=new CsrfTokenRequestAttributeHandler();http.csrf(c->c.csrfTokenRepository(CookieCsrfTokenRepository.withHttpOnlyFalse()).csrfTokenRequestHandler(handler).ignoringRequestMatchers("/api/auth/login","/api/auth/register")).cors(c->{}).authorizeHttpRequests(a->a.requestMatchers("/api/auth/**","/api/scholarships/**","/api/match").permitAll().anyRequest().authenticated()).formLogin(f->f.disable()).httpBasic(b->b.disable()); return http.build();}
 @Bean CorsConfigurationSource corsConfigurationSource(@Value("${app.cors-origin}") String origin){var c=new CorsConfiguration();c.setAllowedOrigins(List.of(origin,"http://127.0.0.1:5500"));c.setAllowedMethods(List.of("GET","POST","PUT","DELETE","OPTIONS"));c.setAllowedHeaders(List.of("Content-Type","X-Requested-With","X-XSRF-TOKEN"));c.setAllowCredentials(true);var s=new UrlBasedCorsConfigurationSource();s.registerCorsConfiguration("/**",c);return s;}
}
